const biz = $input.item.json;
const config = biz.intent_config || {};
const subreddits = [];

// Use discovered subreddits from intent config, or fallback to industry defaults
const discovered = config.discovered?.reddit || [];
for (const sub of discovered.slice(0, 5)) {
  subreddits.push(sub.replace('r/', ''));
}

if (subreddits.length === 0) return [];

const results = [];
for (const sub of subreddits) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://www.reddit.com/r/${sub}/hot.json?limit=10`,
      headers: { 'User-Agent': 'ContentEngine/1.0' },
    });
    const posts = res?.data?.children || [];
    for (const p of posts) {
      const d = p.data;
      if (d.score < 50) continue; // Only trending posts
      results.push({
        business_id: biz.id,
        topic: d.title,
        source: 'reddit',
        source_detail: `r/${sub}`,
        score: d.score,
        url: `https://reddit.com${d.permalink}`,
      });
    }
  } catch(e) { /* skip failed subreddit */ }
  await new Promise(r => setTimeout(r, 1000));
}

return results.slice(0, 10).map(r => ({ json: { ...r, business_context: biz.brand_voice } }));

