const item = $input.item.json;
let score = 0.5;
try {
  const text = item.content?.[0]?.text || '';
  const clean = text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  score = parsed.score || 0.5;
} catch(e) {}

if (score < 0.4) return []; // Skip irrelevant topics

return [{ json: {
  business_id: item.business_id,
  topic: item.topic,
  source: item.source,
  source_detail: item.source_detail,
  relevance_score: score,
} }];

const biz = $input.item.json;
const config = biz.intent_config || {};
const keywords = config.keywords || [];
if (keywords.length === 0) return [];

// Use Google Trends via SerpAPI (requires SERPAPI_KEY env var)
// Falls back gracefully if not configured
const apiKey = $env.SERPAPI_KEY;
if (!apiKey) return []; // Google Trends not configured — Reddit-only mode

const results = [];
for (const kw of keywords.slice(0, 3)) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://serpapi.com/search.json?engine=google_trends&q=${encodeURIComponent(kw)}&data_type=RELATED_QUERIES&api_key=${apiKey}`,
    });
    const rising = res?.related_queries?.rising || [];
    for (const q of rising.slice(0, 3)) {
      results.push({
        business_id: biz.id,
        topic: q.query,
        source: 'google_trends',
        source_detail: `Related to: ${kw}`,
        business_context: biz.brand_voice,
      });
    }
  } catch(e) { /* skip on error */ }
  await new Promise(r => setTimeout(r, 500));
}

return results.map(r => ({ json: r }));
